from typing import Dict

Sequence_ = Dict[int, int]  # finitely supported integer sequence f : N -> Z

def in_tail_zero_ideal(f: Sequence_, n: int) -> bool:
    """True iff f vanishes from index n onward (f in S_n)."""
    return all(v == 0 for i, v in f.items() if i >= n)

def spike(n: int) -> Sequence_:
    """Separating witness e_n: 1 at index n, 0 elsewhere."""
    return {n: 1}

def demo(depth: int = 8) -> None:
    for n in range(depth):
        e = spike(n)
        below = in_tail_zero_ideal(e, n)
        above = in_tail_zero_ideal(e, n + 1)
        print(f"e_{n}: in S_{n}? {below}  in S_{n+1}? {above}  "
              f"strict: {above and not below}")
    print("S_0 = {0}; intersection of all S_n = {0} = S_0 (loops back).")

if __name__ == "__main__":
    demo()

from fractions import Fraction
from typing import List, Set, Tuple

Monomial = Tuple[Fraction, Set[int]]   # (coefficient, variable support)
Polynomial = List[Monomial]

def apply_phi(poly: Polynomial, s: Set[int]) -> Polynomial:
    """Substitute x_i = 0 for i in s; a monomial dies iff it touches s."""
    return [(c, sup) for (c, sup) in poly if not (sup & s)]

def in_variable_ideal(poly: Polynomial, gens: Set[int]) -> bool:
    """poly in <x_i : i in gens> iff killing the generators annihilates poly."""
    return all(c == 0 for c, _ in apply_phi(poly, gens))

def variable(j: int) -> Polynomial:
    return [(Fraction(1), {j})]

def demo(depth: int = 8) -> None:
    for n in range(depth):
        xn = variable(n)
        below = in_variable_ideal(xn, set(range(n)))
        above = in_variable_ideal(xn, set(range(n + 1)))
        print(f"x_{n}: in V_{n}? {below}  in V_{n+1}? {above}  "
              f"strict: {above and not below}")
    print("V_0 = <> = {0}; intersection of all V_n = {0} = V_0 (loops back).")

if __name__ == "__main__":
    demo()

from dataclasses import dataclass
from typing import Union

@dataclass(frozen=True)
class Report:
    ring: str
    has_staircase: bool
    height: str
    reason: str

def polynomial_report(num_vars: Union[int, str]) -> Report:
    if num_vars == "infinity":
        return Report("k[x_0, x_1, ...]", True, "infinite (>= omega)",
                      "explicit variable-ideal staircase")
    n = int(num_vars)
    name = f"k[x_0..x_{n-1}]" if n > 0 else "k"
    return Report(name, False, "0", "Hilbert Basis Theorem => Noetherian")

def demo() -> None:
    for nv in [0, 1, 2, 3, "infinity"]:
        r = polynomial_report(nv)
        print(f"{r.ring:16s} staircase={r.has_staircase!s:5} "
              f"height={r.height:20s} ({r.reason})")
    for ring, has, h, why in [
        ("Z_p (p-adic)", False, "0", "DVR => PID => Noetherian"),
        ("Z^N", True, "infinite", "tail-vanishing staircase"),
        ("alg. integers", True, "infinite", "non-Noetherian => staircase"),
    ]:
        print(f"{ring:16s} staircase={has!s:5} height={h:20s} ({why})")

if __name__ == "__main__":
    demo()

