function verify_staircase(member, witness, N):
    for n in 0 .. N-1:
        w <- witness(n)
        in_lower  <- member(w, n)        # w in rung n?
        in_upper  <- member(w, n+1)      # w in rung n+1?
        if not (in_upper and not in_lower):
            return (False, n)            # strictness fails at level n
    return (True, N)                     # strict up to depth N

