function in_variable_ideal(poly, s):
    residue <- 0
    for (coeff, support) in monomials(poly):
        if support and s are disjoint:      # monomial survives phi_s
            residue <- residue + coeff * monomial(support)
    return residue == 0                     # annihilated => in ideal

function escher_height(num_vars, depth):
    if num_vars is finite:
        return (height = 0, certificate = none)   # Hilbert Basis Theorem
    else:
        chain <- [ generators {0,1,...,n-1} for n in 0..depth ]
        return (height = 'infinite (>= omega)', certificate = chain)

